-- Read-only verification. Select target database first.
SET NAMES utf8mb4;
SELECT p.project_code,p.project_name,v.version_code,v.version_name,v.lifecycle_status,v.data_status,(SELECT COUNT(*) FROM energy_dataset_file f WHERE f.version_id=v.version_id) AS frozen_files FROM energy_project p JOIN energy_project_version v ON v.project_id=p.project_id WHERE p.project_code=CONVERT(0x616c676f726974686d5f64656d6f5f3230323631313130 USING utf8mb4) ORDER BY v.version_code;
SELECT version_code,version_name,status,data_status,JSON_CONTAINS_PATH(files_json,'one','$."locomotive_curves.json"') AS has_curves FROM single_version WHERE project_code=CONVERT(0x616c676f726974686d5f64656d6f5f3230323631313130 USING utf8mb4);
SELECT dept_id,project_code,enabled FROM energy_dept_project WHERE project_code=CONVERT(0x616c676f726974686d5f64656d6f5f3230323631313130 USING utf8mb4);
SELECT dept_id,project_code,enabled FROM single_dept_project WHERE project_code=CONVERT(0x616c676f726974686d5f64656d6f5f3230323631313130 USING utf8mb4);
SELECT 'planning_sites' AS item,COUNT(*) AS rows_found FROM energy_storage_candidate_site WHERE version_id=CONVERT(0x34663239613231642d623835302d353433332d383239642d323036373433366166306534 USING utf8mb4) UNION ALL SELECT 'planning_technologies',COUNT(*) FROM energy_storage_technology WHERE version_id=CONVERT(0x34663239613231642d623835302d353433332d383239642d323036373433366166306534 USING utf8mb4) UNION ALL SELECT 'planning_scenarios',COUNT(*) FROM energy_storage_planning_scenario WHERE version_id=CONVERT(0x34663239613231642d623835302d353433332d383239642d323036373433366166306534 USING utf8mb4) UNION ALL SELECT 'planning_policy',COUNT(*) FROM energy_storage_planning_policy WHERE version_id=CONVERT(0x34663239613231642d623835302d353433332d383239642d323036373433366166306534 USING utf8mb4);
